package com.bank.fk;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.logging.Logger;

public class LedgerDao {
    private static final Logger log = Logger.getLogger(LedgerDao.class.getName());
    private final Connection conn;

    public LedgerDao(Connection conn) { this.conn = conn; }

    // Insert a transaction — FK ensures the account must exist.
    public boolean addTransaction(String txnId, String accountId, BigDecimal amount) {
        try (PreparedStatement ps = conn.prepareStatement(
                "INSERT INTO transactions (txn_id, account_id, amount) VALUES (?,?,?)")) {
            ps.setString(1, txnId); ps.setString(2, accountId); ps.setBigDecimal(3, amount);
            ps.executeUpdate();
            log.info(() -> "Inserted " + txnId + " for " + accountId);
            return true;
        } catch (SQLException e) {
            log.severe("Rejected " + txnId + ": " + e.getMessage());  // FK violation if account missing
            return false;
        }
    }

    // Attempt to delete an account — RESTRICT blocks it if transactions reference it.
    public boolean deleteAccount(String accountId) {
        try (PreparedStatement ps = conn.prepareStatement("DELETE FROM accounts WHERE id = ?")) {
            ps.setString(1, accountId);
            ps.executeUpdate();
            log.info(() -> "Deleted account " + accountId);
            return true;
        } catch (SQLException e) {
            log.severe("Cannot delete " + accountId + ": " + e.getMessage());  // RESTRICT
            return false;
        }
    }
}
