package com.bank.fk;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.DriverManager;
import java.util.logging.Logger;

public class ForeignKeyDemo {
    private static final Logger log = Logger.getLogger(ForeignKeyDemo.class.getName());

    public static void main(String[] args) throws Exception {
        try (Connection conn = DriverManager.getConnection(
                "jdbc:postgresql://localhost:5432/bankdb", "bank_app", "secret")) {
            LedgerDao dao = new LedgerDao(conn);

            // 1. Orphan transaction (account ZZZ9999 does not exist) → rejected by FK.
            dao.addTransaction("TXN-9999", "ZZZ9999", new BigDecimal("1000.00"));

            // 2. Delete account that HAS transactions → blocked by ON DELETE RESTRICT.
            dao.deleteAccount("SAV2001");

            // 3. Delete Priya (no transactions) → succeeds; her prefs CASCADE-delete.
            dao.deleteAccount("CUR3001");

            log.info("FK blocks orphans; RESTRICT protects history; CASCADE cleans dependents.");
        }
    }
}
